const content = $input.first().json.ai_response;
const topic = $input.first().json.topic;

// Split content into tweet-sized chunks
const sentences = content.split('. ');
const tweets = [];
let currentTweet = '';

for (const sentence of sentences) {
  if ((currentTweet + sentence + '. ').length <= 280) {
    currentTweet += sentence + '. ';
  } else {
    if (currentTweet) tweets.push(currentTweet.trim());
    currentTweet = sentence + '. ';
  }
}
if (currentTweet) tweets.push(currentTweet.trim());

// Add thread indicators
const formattedTweets = tweets.map((tweet, i) => {
  const indicator = tweets.length > 1 ? `(${i + 1}/${tweets.length}) ` : '';
  return indicator + tweet;
});

// Add hashtags
const hashtags = `#${topic.replace(/\s+/g, '')} #[PRODUCT_NAME] #tech`;
formattedTweets[formattedTweets.length - 1] += `\n\n${hashtags}`;

return [{json: {...$input.first().json, formatted_content: formattedTweets, platform: 'twitter'}}];

