if (sub && sub.items.data[0].price.recurring.interval === 'year') healthScore += 15;
if (sub && sub.discount) healthScore += 10;

// Usage-based adjustments (would integrate with your analytics)
const usage = await getCustomerUsage(customerId);
if (usage > 1000) healthScore += 15;
if (usage > 5000) healthScore += 10;

return [{
  json: {
    ...sub,
    health_score: Math.min(100, healthScore),
    usage,
    risk_level: healthScore < 40 ? 'high' : healthScore < 70 ? 'medium' : 'low'
  }
}];

